INSERT INTO `competencies` VALUES (2,'C1',4,'Analiza un problema y elabora una solución algorítmica y/o de ingeniería en el área de software de forma adecuada con el fin de solucionar problemáticas en contextos industriales, organizaci','Analiza un problema y elabora una solución algorítmica y/o de ingeniería en el área de software de forma adecuada con el fin de solucionar problemáticas en contextos industriales, organizacionales o sociales en un nivel básico.',1,'2026-08-31 00:31:22','2026-08-31 00:31:22'),(3,'C2',4,'Diseña software a partir de sistemas, componentes o procesos, seguros con el fin de satisfacer las necesidades en contextos económicos, ambientales, sociales, políticos, éticos, de salud y d','Diseña software a partir de sistemas, componentes o procesos, seguros con el fin de satisfacer las necesidades en contextos económicos, ambientales, sociales, políticos, éticos, de salud y de la seguridad de las organizaciones.​',1,'2026-08-31 00:31:22','2026-08-31 00:31:22'),(4,'C3',4,'Analiza el impacto global de las soluciones de software en las personas, las organizaciones y la sociedad con el fin de garantizar la integridad del ser humano y la sostenibilidad de los rec','Analiza el impacto global de las soluciones de software en las personas, las organizaciones y la sociedad con el fin de garantizar la integridad del ser humano y la sostenibilidad de los recursos ambientales.​',1,'2026-08-31 00:31:22','2026-08-31 00:31:22'),(5,'C4',4,'Desarrolla, integra y gestiona software aplicado a la inteligencia artificial, las aplicaciones móviles, la visualización y el análisis de los datos como aporte al desarrollo económico y soc','Desarrolla, integra y gestiona software aplicado a la inteligencia artificial, las aplicaciones móviles, la visualización y el análisis de los datos como aporte al desarrollo económico y social del país.​',1,'2026-08-31 00:31:22','2026-08-31 00:31:22'),(6,'C5',4,'Evalúa e investiga nuevas ideas, así como nuevas fuentes de información con el fin de desarrollar capacidades que le permiten un aprendizaje permanente.​','Evalúa e investiga nuevas ideas, así como nuevas fuentes de información con el fin de desarrollar capacidades que le permiten un aprendizaje permanente.​',1,'2026-08-31 00:31:22','2026-08-31 00:31:22');
