INSERT INTO `microcurricular_learning_outcomes` VALUES (1,1,'RA1',1,NULL,'Identifica modelos simbólicos de problemas aplicados descritos en lenguaje natural.',1,'2026-04-29 19:42:01','2026-08-31 01:43:26'),(2,1,'RA2',2,NULL,'Desarrolla algoritmos para resolver problemas simples y rastrear la ejecución de programas de computador.',1,'2026-05-06 19:11:12','2026-08-31 01:43:26'),(3,1,'RA3',2,NULL,'Desarrolla algoritmos para resolver problemas simples y rastrear la ejecución de programas de computador. (H)',1,'2026-05-06 19:11:41','2026-05-06 19:11:41'),(4,10,'RA24',1,NULL,'Identifica el impacto de las soluciones a un problema de ingeniería en un contexto global y social.',1,'2026-08-31 01:37:40','2026-08-31 01:37:40'),(5,10,'RA26',2,NULL,'Propone proyectos para solucionar necesidades actuales en su contexto de manera sostenible, optimizando la idea general de creación de valor dual -económico y social.',1,'2026-08-31 01:37:40','2026-08-31 01:37:40'),(6,10,'RA27',3,NULL,'Asume responsabilidades en el cuidado del medio ambiente, contribuyendo desde su perfil profesional con el desarrollo sostenible.',1,'2026-08-31 01:37:40','2026-08-31 01:37:40'),(7,10,'RA19',1,NULL,'Conoce los criterios básicos para el análisis técnico, social, ético y ambiental de los proyectos en ingeniería, identificando problemáticas regionales, nacionales e internacionales, a las que se pueden aportar soluciones desde la ingeniería con enfoque sostenible',1,'2026-08-31 01:37:42','2026-08-31 01:37:42'),(8,10,'RA20',2,NULL,'Desarrolla eficientemente búsquedas de información.',1,'2026-08-31 01:37:42','2026-08-31 01:37:42'),(9,10,'RA21',3,NULL,'Reconoce la importancia de la sostenibilidad en el desarrollo de proyectos de ingeniería.',1,'2026-08-31 01:37:42','2026-08-31 01:37:42'),(10,14,'RA31',2,NULL,'Diseña repositorios de datos con el fin de dar solución a los requerimientos de un sistema de información, aplicación y/o software.',1,'2026-08-31 01:37:48','2026-08-31 01:37:48'),(11,32,'RA56',1,NULL,'Id