INSERT INTO `performance_levels` VALUES (1,'Insuficiente','El estudiante no alcanza el nivel mínimo de competencia esperado. Se evidencian brechas significativas en conocimientos, habilidades o actitudes.',1,1.30,0,1,'2026-04-29 18:30:42','2026-08-30 10:01:16'),(2,'Básico','El estudiante alcanza el nivel mínimo esperado con profundidad limitada. El desempeño es aceptable pero carece de consistencia o amplitud.',2,2.50,1,1,'2026-04-29 18:30:42','2026-08-30 09:48:29'),(3,'Competente','El estudiante demuestra de forma consistente la competencia esperada con comprensión sólida y aplicación confiable.',3,3.80,0,1,'2026-04-29 18:30:42','2026-04-29 18:30:42'),(4,'Destacado','El estudiante supera las expectativas, demostrando dominio sobresaliente, pensamiento crítico y capacidad para transferir competencias a situaciones nuevas.',4,5.00,0,1,'2026-04-29 18:30:42','2026-08-30 10:01:26');
